std::string read_admit_mode_str = "none";
uint32_t    read_admit_mode_val = 0;
// +read-admit-measure-only=0|1 (default 0).  While it is 1 and the post-warm
// measurement phase is NOT active (reset ticks, warm-up and the warm A
// drain), tick() forces read_admit_mode_i to 1, i.e. the SAME single-slot
// proxy buffer used by +read-admit=buffer.  From measurement_phase onward
// the requested read_admit_mode_val is driven unchanged, so the measured
// window keeps the requested admission mode while the warm phase runs the
// buffer.  Default false reproduces the previous behaviour exactly.
bool        read_admit_measure_only = false;

if (const char* v = val("read-period")) read_period = (uint32_t)std::strtoul(v, nullptr, 0);
if (const char* v = val("read-admit-measure-only")) {
    char* end = nullptr;
    const unsigned long parsed = std::strtoul(v, &end, 0);
    if (end == v || *end != '\0' || parsed > 1) {
        std::fprintf(stderr,
            "nonblock_actual_dma_test: invalid +read-admit-measure-only='%s' (expected 0|1)\n", v);
        return 2;
    }
    read_admit_measure_only = (parsed != 0);
}

tb.read_admit_mode_str = read_admit;
tb.read_admit_mode_val = read_admit_val;
tb.read_admit_measure_only = read_admit_measure_only;
